        atomicAdd(&G[((0 * n_atom + aa) * 3 + 2)], (sq * g0A2));
        atomicAdd(&G[((0 * n_atom + ab) * 3 + 0)], (sq * g0B0));
        atomicAdd(&G[((0 * n_atom + ab) * 3 + 1)], (sq * g0B1));
        atomicAdd(&G[((0 * n_atom + ab) * 3 + 2)], (sq * g0B2));
        atomicAdd(&G[((1 * n_atom + aa) * 3 + 0)], (sq * g1A0));
        atomicAdd(&G[((1 * n_atom + aa) * 3 + 1)], (sq * g1A1));
        atomicAdd(&G[((1 * n_atom + aa) * 3 + 2)], (sq * g1A2));
        atomicAdd(&G[((1 * n_atom + ab) * 3 + 0)], (sq * g1B0));
        atomicAdd(&G[((1 * n_atom + ab) * 3 + 1)], (sq * g1B1));
        atomicAdd(&G[((1 * n_atom + ab) * 3 + 2)], (sq * g1B2));
        atomicAdd(&G[((2 * n_atom + aa) * 3 + 0)], (sq * g2A0));
        atomicAdd(&G[((2 * n_atom + aa) * 3 + 1)], (sq * g2A1));
        atomicAdd(&G[((2 * n_atom + aa) * 3 + 2)], (sq * g2A2));
        atomicAdd(&G[((2 * n_atom + ab) * 3 + 0)], (sq * g2B0));
        atomicAdd(&G[((2 * n_atom + ab) * 3 + 1)], (sq * g2B1));
        atomicAdd(&G[((2 * n_atom + ab) * 3 + 2)], (sq * g2B2));
    }
}
